table.rules:
table inet sp1obs_q1 {
  chain output {
    type filter hook output priority -10; policy accept;
    ip daddr 10.255.255.254 counter reject
    ip daddr 192.0.2.0/24 meta l4proto tcp counter reject with tcp reset
    ip daddr 192.0.2.0/24 counter reject
  }
}

table inet sp1obs_q1 {
  chain output {
    type filter hook output priority -10; policy accept;
    ip daddr 10.255.255.254 counter reject
    fib daddr type local accept
    meta l4proto tcp counter reject with tcp reset
    meta l4proto udp counter reject with icmpx port-unreachable
    counter reject with icmpx admin-prohibited
  }
  chain forward {
    type filter hook forward priority -10; policy drop;
    counter drop
  }
}
